@Configuration
class PasswordConfig {
    @Bean
    PasswordEncoder passwordEncoder() {
        String id = "argon2";
        Map<String, PasswordEncoder> encoders = Map.of(
            "argon2", new Argon2PasswordEncoder(16, 32, 1, 19 * 1024, 2),
            "bcrypt", new BCryptPasswordEncoder());
        return new DelegatingPasswordEncoder(id, encoders);
    }
}

@Service
class LoginService {
    boolean verifyAndUpgrade(User user, CharSequence candidate) {
        if (!encoder.matches(candidate, user.passwordHash())) return false;
        if (encoder.upgradeEncoding(user.passwordHash())) {
            user.changePasswordHash(encoder.encode(candidate));
            repository.save(user);
        }
        return true;
    }
}
```
*Benchmark the chosen parameters and keep old algorithm mappings until their stored verifiers have been migrated or reset.*

